8	// Preview 预演一批装载、卸下、移动操作，返回这批安排按当前配载完成后的
9	// 预计结果。
10	//
11	// 预览是只读的：无论结果能否提交，货物位置、舱位占用与已成功调整记录
12	// 都不会改变，也不占用任何调整编号。清单沿用与 Adjust 相同的 Op 表示
13	// 与编号规则，逐条合法性（货物与舱位是否存在、货物状态、重复操作、
14	// 移动到原舱位等）与正式提交完全一致：某条操作不合法时，按输入顺序
15	// 返回第一个非法操作的现有错误，不返回局部预览。
16	//
17	// 每条操作本身合法时始终返回完整预览：预计配载违反承重或混装限制时
18	// Submittable 为 false，并在 Rejections 中一次列全全部受影响舱位的
19	// 拒绝原因；判断以整批操作完成后的最终配载为准，不会因中间步骤暂时
20	// 超重而拒绝最终合法的交换。
21	//
22	// 预览反映调用时刻登记处的一致快照（登记、配载与已成功调整记录取自
23	// 同一时刻，不会混入并发调整前后的状态）。返回内容是独立快照，调用
24	// 方修改不影响登记处或之后的预览；状态未变时连续预览同一清单结果
25	// 一致。正式提交仍以提交时状态重新判断，不能凭旧预览直接放行。
26	func (r *Registry) Preview(ops []Op) (*PreviewResult, error) {
27		r.mu.Lock()
28		defer r.mu.Unlock()
29	
30		if len(ops) == 0 {
31			return nil, fail(ErrEmptyAdjustment, "", "预览清单不包含任何操作")
32		}
33	
34		// 与正式提交共用同一套逐条校验与最终配载模拟；预览不带调整编号。
35		vops, final, affected, err := r.prepareOps(ops, fail)
36		if err != nil {
37			return nil, err
38		}
39	
40		// 涉及货物的原舱位与预计舱位，按货物编号字典序排列。
41		cargoChanges := make([]CargoChange, 0, len(vops))
42		for _, v := range vops {
43			c := v.cargo
44			change := CargoChange{CargoID: c.id, From: c.compartmentID}
45			switch v.op.Kind {
46			case OpLoad, OpMove:
47				change.To = v.target.id
48			case OpUnload:
49				change.To = ""
50			}
51			cargoChanges = append(cargoChanges, change)
52		}
53		sort.Slice(cargoChanges, func(i, j int) bool {
54			return cargoChanges[i].CargoID < cargoChanges[j].CargoID
55		})
56	
57		// 受影响舱位调整前后的完整配载，按舱位编号字典序排列。交换中总重量
58		// 不变的两个舱位同样列出。
59		compIDs := make([]string, 0, len(affected))
60		for id := range affected {
61			compIDs = append(compIDs, id)
62		}
63		sort.Strings(compIDs)
64		compartments := make([]CompartmentPreview, 0, len(compIDs))
65		for _, id := range compIDs {
66			compartments = append(compartments, CompartmentPreview{
67				ID:     id,
68				Before: *compartmentView(r.compartments[id]),
69				After:  compartmentAfterView(r.compartments[id], final[id]),
70			})
71		}
72	
73		// 预计配载的全部拒绝原因，按舱位编号排列、同舱先重量后混装。
74		rejs := r.evaluateFinal(final)
75		sort.SliceStable(rejs, func(i, j int) bool {
76			if rejs[i].CompartmentID != rejs[j].CompartmentID {
77				return rejs[i].CompartmentID < rejs[j].CompartmentID
78			}
79			return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
80		})
81		rejections := make([]Rejection, 0, len(rejs))
82		for _, rej := range rejs {
83			rejections = append(rejections, *cloneRejection(rej))
84		}
85	
86		return &PreviewResult{
87			Submittable:  len(rejections) == 0,
88			CargoChanges: cargoChanges,
89			Compartments: compartments,
90			Rejections:   rejections,
91		}, nil
92	}
93	
94	// compartmentAfterView 构造舱位在模拟配载下的完整快照。
95	// 重量合计溢出 int64 时，已用重量与剩余重量不提供数值（保持零值），
96	// 货物清单照常返回。调用方持锁。
97	func compartmentAfterView(comp *compartment, set map[string]*cargo) CompartmentView {
98		ids := make([]string, 0, len(set))
99		for cid := range set {
100			ids = append(ids, cid)
101		}
102		sort.Strings(ids)
103		cargoViews := make([]CargoView, 0, len(ids))
104		var used int64
105		overflow := false
106		for _, cid := range ids {
107			c := set[cid]
108			view := *cargoView(c)
109			// 预计清单中的货物按模拟配载完成后的所属舱位展示；编号、重量、
110			// 目的地与混装许可仍取登记资料。cargoView 返回的是值副本，改写
111			// 位置字段不影响登记处。
112			view.Loaded = true
113			view.CompartmentID = comp.id
114			cargoViews = append(cargoViews, view)
115			if !overflow {
116				if c.weight > math.MaxInt64-used {
117					overflow = true
118				} else {
119					used += c.weight
120				}
121			}
122		}
123		view := CompartmentView{
124			ID:        comp.id,
125			MaxWeight: comp.maxWeight,
126			Cargo:     cargoViews,
127		}
128		if !overflow {
129			view.UsedWeight = used
130			view.RemainingWeight = comp.maxWeight - used
131		}
132		return view
133	}
134	
135	// cloneRejection 复制拒绝原因中的切片，保证调用方修改不影响其他结果。
136	func cloneRejection(x *Rejection) *Rejection {
137		cp := &Rejection{
138			CompartmentID:   x.CompartmentID,
139			Kind:            x.Kind,
140			MaxWeight:       x.MaxWeight,
141			UsedWeight:      x.UsedWeight,
142			RemainingWeight: x.RemainingWeight,
143			Overweight:      x.Overweight,
144		}
145		if x.Destinations != nil {
146			cp.Destinations = make([]MixedDestination, len(x.Destinations))
147			for i, d := range x.Destinations {
148				cp.Destinations[i] = MixedDestination{
149					Destination: d.Destination,
150					CargoIDs:    append([]string(nil), d.CargoIDs...),
151				}
152			}
153		}
154		if x.OffendingCargo != nil {
155			cp.OffendingCargo = append([]string(nil), x.OffendingCargo...)
156		}
157		return cp
158	}
