package stowage

import (
	"math"
	"sort"
)

// Preview 预演一批装载、卸下、移动操作，返回这批安排按当前配载完成后的
// 预计结果。
//
// 预览是只读的：无论结果能否提交，货物位置、舱位占用与已成功调整记录
// 都不会改变，也不占用任何调整编号。清单沿用与 Adjust 相同的 Op 表示
// 与编号规则，逐条合法性（货物与舱位是否存在、货物状态、重复操作、
// 移动到原舱位等）与正式提交完全一致：某条操作不合法时，按输入顺序
// 返回第一个非法操作的现有错误，不返回局部预览。
//
// 每条操作本身合法时始终返回完整预览：预计配载违反承重或混装限制时
// Submittable 为 false，并在 Rejections 中一次列全全部受影响舱位的
// 拒绝原因；判断以整批操作完成后的最终配载为准，不会因中间步骤暂时
// 超重而拒绝最终合法的交换。
//
// 预览反映调用时刻登记处的一致快照（登记、配载与已成功调整记录取自
// 同一时刻，不会混入并发调整前后的状态）。返回内容是独立快照，调用
// 方修改不影响登记处或之后的预览；状态未变时连续预览同一清单结果
// 一致。正式提交仍以提交时状态重新判断，不能凭旧预览直接放行。
func (r *Registry) Preview(ops []Op) (*PreviewResult, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if len(ops) == 0 {
		return nil, fail(ErrEmptyAdjustment, "", "预览清单不包含任何操作")
	}

	// 与正式提交共用同一套逐条校验与最终配载模拟；预览不带调整编号。
	vops, final, affected, err := r.prepareOps(ops, fail)
	if err != nil {
		return nil, err
	}

	// 涉及货物的原舱位与预计舱位，按货物编号字典序排列。
	cargoChanges := make([]CargoChange, 0, len(vops))
	for _, v := range vops {
		c := v.cargo
		change := CargoChange{CargoID: c.id, From: c.compartmentID}
		switch v.op.Kind {
		case OpLoad, OpMove:
			change.To = v.target.id
		case OpUnload:
			change.To = ""
		}
		cargoChanges = append(cargoChanges, change)
	}
	sort.Slice(cargoChanges, func(i, j int) bool {
		return cargoChanges[i].CargoID < cargoChanges[j].CargoID
	})

	// 受影响舱位调整前后的完整配载，按舱位编号字典序排列。交换中总重量
	// 不变的两个舱位同样列出。
	compIDs := make([]string, 0, len(affected))
	for id := range affected {
		compIDs = append(compIDs, id)
	}
	sort.Strings(compIDs)
	compartments := make([]CompartmentPreview, 0, len(compIDs))
	for _, id := range compIDs {
		compartments = append(compartments, CompartmentPreview{
			ID:     id,
			Before: *compartmentView(r.compartments[id]),
			After:  compartmentAfterView(r.compartments[id], final[id]),
		})
	}

	// 预计配载的全部拒绝原因，按舱位编号排列、同舱先重量后混装。
	rejs := r.evaluateFinal(final)
	sort.SliceStable(rejs, func(i, j int) bool {
		if rejs[i].CompartmentID != rejs[j].CompartmentID {
			return rejs[i].CompartmentID < rejs[j].CompartmentID
		}
		return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
	})
	rejections := make([]Rejection, 0, len(rejs))
	for _, rej := range rejs {
		rejections = append(rejections, *cloneRejection(rej))
	}

	return &PreviewResult{
		Submittable:  len(rejections) == 0,
		CargoChanges: cargoChanges,
		Compartments: compartments,
		Rejections:   rejections,
	}, nil
}

// compartmentAfterView 构造舱位在模拟配载下的完整快照。
// 重量合计溢出 int64 时，已用重量与剩余重量不提供数值（保持零值），
// 货物清单照常返回。调用方持锁。
func compartmentAfterView(comp *compartment, set map[string]*cargo) CompartmentView {
	ids := make([]string, 0, len(set))
	for cid := range set {
		ids = append(ids, cid)
	}
	sort.Strings(ids)
	cargoViews := make([]CargoView, 0, len(ids))
	var used int64
	overflow := false
	for _, cid := range ids {
		c := set[cid]
		view := *cargoView(c)
		// 预计清单中的货物按模拟配载完成后的所属舱位展示；编号、重量、
		// 目的地与混装许可仍取登记资料。cargoView 返回的是值副本，改写
		// 位置字段不影响登记处。
		view.Loaded = true
		view.CompartmentID = comp.id
		cargoViews = append(cargoViews, view)
		if !overflow {
			if c.weight > math.MaxInt64-used {
				overflow = true
			} else {
				used += c.weight
			}
		}
	}
	view := CompartmentView{
		ID:        comp.id,
		MaxWeight: comp.maxWeight,
		Cargo:     cargoViews,
	}
	if !overflow {
		view.UsedWeight = used
		view.RemainingWeight = comp.maxWeight - used
	}
	return view
}

// cloneRejection 复制拒绝原因中的切片，保证调用方修改不影响其他结果。
func cloneRejection(x *Rejection) *Rejection {
	cp := &Rejection{
		CompartmentID:   x.CompartmentID,
		Kind:            x.Kind,
		MaxWeight:       x.MaxWeight,
		UsedWeight:      x.UsedWeight,
		RemainingWeight: x.RemainingWeight,
		Overweight:      x.Overweight,
	}
	if x.Destinations != nil {
		cp.Destinations = make([]MixedDestination, len(x.Destinations))
		for i, d := range x.Destinations {
			cp.Destinations[i] = MixedDestination{
				Destination: d.Destination,
				CargoIDs:    append([]string(nil), d.CargoIDs...),
			}
		}
	}
	if x.OffendingCargo != nil {
		cp.OffendingCargo = append([]string(nil), x.OffendingCargo...)
	}
	return cp
}

package stowage

// OpKind 表示调整操作的种类。
type OpKind int

const (
	// OpLoad 装载：将未装载的货物装入目标舱位。
	OpLoad OpKind = iota
	// OpUnload 卸下：将已装载的货物从当前舱位移除，货物记录保留。
	OpUnload
	// OpMove 移动：将已装载的货物直接改放到目标舱位。
	OpMove
)

// String 返回操作种类名称。
func (k OpKind) String() string {
	switch k {
	case OpLoad:
		return "装载"
	case OpUnload:
		return "卸下"
	case OpMove:
		return "移动"
	default:
		return "未知"
	}
}

// Op 是一次调整中的单个操作。
type Op struct {
	Kind    OpKind
	CargoID string
	Target  string // 装载/移动时的目标舱位；卸下时忽略
}

// CargoChange 记录一件货物调整前后的所属舱位。
type CargoChange struct {
	CargoID string
	From    string // 空字符串表示未装载
	To      string // 空字符串表示未装载
}

// CompartmentChange 记录一个舱位调整前后的总重量。
type CompartmentChange struct {
	CompartmentID string
	WeightBefore  int64
	WeightAfter   int64
}

// AdjustmentResult 是一次成功调整的结果快照。
type AdjustmentResult struct {
	ID                 string
	CargoChanges       []CargoChange
	CompartmentChanges []CompartmentChange
}

// CargoView 是货物信息的独立快照。
type CargoView struct {
	ID            string
	Weight        int64
	Destination   string
	AllowMixed    bool
	Loaded        bool
	CompartmentID string // 空字符串表示未装载
}

// CompartmentView 是舱位信息的独立快照。
type CompartmentView struct {
	ID              string
	MaxWeight       int64
	UsedWeight      int64
	RemainingWeight int64
	Cargo           []CargoView // 按编号字典序排列
}

// MixedDestination 描述预计配载中一个舱位内某个目的地对应的全部货物。
type MixedDestination struct {
	Destination string
	CargoIDs    []string // 按编号字典序排列
}

// Rejection 描述预计配载中单个舱位的一条拒绝原因。
//
// Kind 为 ErrOverweight 时，UsedWeight、RemainingWeight、Overweight 与
// MaxWeight 均有效；Kind 为 ErrOverflow（重量溢出）时，预计已用重量、
// 剩余重量与超出量无法用 int64 表示，对应数值字段保持零值，仅提供
// MaxWeight、货物清单与混装原因；Kind 为 ErrMixedLoading 时，
// Destinations 给出各目的地对应的货物，OffendingCargo 列出其中全部
// 不允许混装的货物编号。
type Rejection struct {
	CompartmentID   string
	Kind            ErrorKind
	MaxWeight       int64
	UsedWeight      int64              // 超重时为预计总重量；溢出或混装时为零值
	RemainingWeight int64              // 超重时为预计剩余重量（负值）；其余为零值
	Overweight      int64              // 超重时为超出承重的千克数；其余为零值
	Destinations    []MixedDestination // 混装冲突时各目的地及其货物，按目的地字典序排列
	OffendingCargo  []string           // 混装冲突时全部不允许混装的货物编号，字典序排列
}

// CompartmentPreview 是受影响舱位调整前后的完整配载快照。
// Before 反映调整前配载，清单中的货物保持原所属舱位；After 反映预计
// 配载，清单中的货物一律显示为已装载且属于该舱位，编号、重量、目的地
// 与混装许可仍取登记资料。预计超重时 RemainingWeight 为负值；预计重量
// 溢出 int64 时 After 不提供已用与剩余重量数值（保持零值），货物清单
// 照常返回。
type CompartmentPreview struct {
	ID     string
	Before CompartmentView
	After  CompartmentView
}

// PreviewResult 是一次预览的完整结果，本身是与登记处状态无关的独立快照。
type PreviewResult struct {
	// Submittable 表示按当前登记处状态，这组操作能否作为一次调整提交。
	Submittable bool
	// CargoChanges 列出清单涉及货物的原舱位与预计舱位，按货物编号字典序排列；
	// 未装载用空编号表示。
	CargoChanges []CargoChange
	// Compartments 列出全部受影响舱位调整前后的完整货物清单、已用重量与
	// 剩余重量，按舱位编号字典序排列。即使交换后总重量不变也会列出。
	Compartments []CompartmentPreview
	// Rejections 列出预计配载的全部拒绝原因，按舱位编号排列，同一舱位
	// 先重量（超重/溢出）后混装。为空表示 Submittable 为 true。
	Rejections []Rejection
}

