655			{Kind: OpLoad, CargoID: "G3", Target: "C1"},
656		}); err != nil {
657			t.Fatal(err)
658		}
659		// 卸下 G3 合法；移动 G1 到 C2 会导致 C2 超重（50+60 > 100），整次失败。
660		se := requireError(t, func() error {
661			_, err := r.Adjust("A2", []Op{
662				{Kind: OpUnload, CargoID: "G3"},        // 合法
663				{Kind: OpMove, CargoID: "G1", Target: "C2"}, // 超重
664			})
665			return err
666		}(), ErrOverweight)
667		if se.ID != "C2" {
668			t.Fatalf("超重应指出舱位，实际 ID=%q", se.ID)
669		}
670		// 三件货物归属都不变。
