// 合计超过 int64 可表示范围时 overflow 为 true、sum 为部分和，调用方不
// 应采用其数值；查询、预览清单与承重/溢出拒绝判断共用同一套汇总规则。
func sumCargoWeight(set map[string]*cargo) (sum int64, overflow bool) {
	for _, c := range set {
		if c.weight > math.MaxInt64-sum {
