	ids := make([]string, 0, len(set))
	for cid := range set {
		ids = append(ids, cid)
	}
	sort.Strings(ids)
	cargoViews := make([]CargoView, 0, len(ids))
	var used int64
	overflow := false
	for _, cid := range ids {
		c := set[cid]
		view := *cargoView(c)
		// 预计清单中的货物按模拟配载完成后的所属舱位展示；编号、重量、
		// 目的地与混装许可仍取登记资料。cargoView 返回的是值副本，改写
		// 位置字段不影响登记处。
